/* Radical Rush: actual hero face portraits for the local character selector.
   Keeps the original <select> element and dispatches its original change event. */
(function () {
  'use strict';
  const FACE_IMAGES = {"hoodie": "data:image/webp;base64,", "astronaut-animated": "data:image/webp;base64,", "dragon-animated": "data:image/webp;base64,", "cowboy-animated": "data:image/webp;base64,", "ninja-animated": "data:image/webp;base64,"};
  const FACE_SHEETS = {"hoodie":"data:image/webp;base64,","astronaut-animated":"data:image/webp;base64,","dragon-animated":"data:image/webp;base64,","cowboy-animated":"data:image/webp;base64,","ninja-animated":"data:image/webp;base64,"};
  const HEROES = [
    ['hoodie','Green Adventurer','Hero'],
    ['astronaut-animated','Blue Astronaut','Astro'],
    ['dragon-animated','Green Dragon','Dragon'],
    ['cowboy-animated','Cowboy Explorer','Cowboy'],
    ['ninja-animated','Shadow Ninja','Ninja']
  ];
  function buildPicker(select, prefix) {
    if (!select || select.dataset.rrFaceReady === 'true') return;
    const holder = document.createElement('div');
    holder.className = 'rr-face-picker';
    holder.setAttribute('role','group');
    holder.setAttribute('aria-label', 'Choose your character');
    const buttons = [];
    for (const [value,name,shortName] of HEROES) {
      if (![...select.options].some(o=>o.value===value)) continue;
      const button = document.createElement('button');
      button.type='button';button.className='rr-face-choice';
      button.dataset.hero=value;
      button.setAttribute('aria-label',name);
      button.title=name;
      // Keep the original still face as fallback, and display an original sprite-frame
      // animation over it when the strip is available. No emoji or replacement art.
      const art=document.createElement('span');art.className='rr-face-art';
      const img=document.createElement('img');img.className='rr-face-image';
      img.src=FACE_IMAGES[value]; img.alt='';img.loading='eager';img.decoding='async';
      art.append(img);
      if (FACE_SHEETS[value]) {
        const motion=document.createElement('span');
        motion.className='rr-face-motion';
        motion.setAttribute('aria-hidden','true');
        motion.style.backgroundImage='url('+JSON.stringify(FACE_SHEETS[value])+')';
        art.append(motion);
        // Reveal the animated face only after its source strip has loaded.
        // This prevents the stationary fallback image from ghosting through
        // transparent parts of a walking frame.
        const preload=new Image();
        preload.onload=()=>art.classList.add('rr-face-ready');
        preload.src=FACE_SHEETS[value];
      }
      const label=document.createElement('span');label.className='rr-face-label';label.textContent=shortName;
      button.append(art,label);
      button.addEventListener('click',()=>{
        select.value=value;
        select.dispatchEvent(new Event('change',{bubbles:true}));
        sync();
      });
      holder.append(button);buttons.push(button);
    }
    if (buttons.length !== HEROES.length) return;
    function sync(){for (const b of buttons) b.setAttribute('aria-pressed', String(b.dataset.hero===select.value));}
    select.addEventListener('change',sync);
    select.classList.add('rr-face-native-select');
    select.dataset.rrFaceReady='true';
    const label=select.closest('label');
    if (label) {
      label.after(holder);
    } else {select.after(holder);}
    sync();
  }
  function localPickers() {
    const group=document.getElementById('playerEditors');if(!group) return;
    group.querySelectorAll('.player-editor select[aria-label$=" character"]').forEach(sel=>buildPicker(sel,'local'));
  }
  function init() {
    localPickers();
    const group=document.getElementById('playerEditors');
    if(group) new MutationObserver(localPickers).observe(group,{childList:true});
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',init,{once:true});
  else init();
})();

  
